import math
def layer_norm(x, eps=1e-5):
    mean = sum(x) / len(x)
    var = sum((v - mean) ** 2 for v in x) / len(x)
    return [(v - mean) / math.sqrt(var + eps) for v in x]
def rms_norm(x, eps=1e-5):
    ms = sum(v * v for v in x) / len(x)
    d = math.sqrt(ms + eps)
    return [v / d for v in x]
x = [4.0, 2.0, 0.0, 6.0]
def rms(v):
    return round(math.sqrt(sum(a * a for a in v) / len(v)), 4)
big = [10 * v for v in x]
print(rms(layer_norm(x)), rms(rms_norm(x)), rms(rms_norm(big)))
